  steps={
    {crafts=33,from=1,mats={{2934,3}},note={de="Wer Leichtes Leder ohnehin kauft, kann diesen Schritt überspringen und gleich mit den Rüstungssets beginnen.",en="If you buy Light Leather anyway, skip this step and start with the armor kits."},rank="apprentice",res={de="Leichtes Leder, gewonnen aus Lederfetzen. Grundmaterial für die nächsten Schritte.",en="Light leather made from ruined scraps. It is the base material for the next steps."},spell=2881,src="trainer",to=30},
    {crafts=20,from=30,mats={{2318,1}},note={de="Das Rezept ist schon zu Beginn gelb, die Anzahl ist ein Richtwert.",en="The recipe is yellow from the start, so the count is an estimate."},rank="apprentice",res={de="Verbrauchbares Rüstungsset, das sich auf ein Rüstungsteil auftragen lässt; der Tooltip nennt die Bedingungen.",en="Consumable armor kit applied to a piece of armor; the tooltip lists the requirements."},spell=2152,src="trainer",to=45},
    {crafts=10,from=45,mats={{2318,3},{2320,2}},rank="apprentice",res={de="Einfache Lederhandschuhe, brauchbar für die eigene Ausrüstung oder zum Verkaufen.",en="Simple leather gloves, usable yourself or for sale."},spell=3756,src="trainer",to=55},
    {crafts=25,from=55,mats={{2318,6},{2320,2}},note={de="Ab Skill 50 den Gesellen-Rang lernen, sonst endet das Maximum bei 75. Alternative bis 125 ohne mittlere Bälge: Geprägte Lederhandschuhe (bis 75), Mittleres Leder, Feiner Ledergürtel, Dunkle Lederstiefel, Dunkler Lederumhang, Dunkle Lederhose und zuletzt Lederhandschuhe des Hügelwächters. Dafür braucht ihr etwa 270 zusätzliche Mittlere Leder statt der 25 Bälge.",en="Learn Journeyman from skill 50 or your cap stays at 75. Alternative up to 125 without medium hides: Embossed Leather Gloves (to 75), Medium Leather, Fine Leather Belt, Dark Leather Boots, Dark Leather Cloak, Dark Leather Pants and finally Hillman's Leather Gloves. This takes about 270 extra Medium Leather instead of the 25 hides."},rank="journeyman",res={de="Lederne Gürtel; alle 25 werden später für die dunklen Ledergürtel gebraucht.",en="Leather belts; keep all 25, they are used up in the dark leather belts later."},spell=3763,src="trainer",to=80},
    {crafts=25,from=80,mats={{4232,1},{4289,1}},note={de="Alle 25 Bälge aufheben. Reichen die Punkte nicht, einige günstige Rezepte zusätzlich herstellen.",en="Keep all 25 hides. If the points fall short, craft a few cheap extras."},rank="journeyman",res={de="Gegerbter Balg als Material für den dunklen Ledergürtel.",en="Cured hides, the material for the dark leather belts."},spell=3817,src="trainer",to=100},
    {crafts=25,from=100,mats={{4246,1},{4233,1},{2321,2},{4340,1}},note={de="Fertigprodukte der letzten Schritte werden hier verbraucht und nicht noch einmal gekauft.",en="The intermediate products from the last steps are used up here, not bought again."},rank="journeyman",res={de="Der Ledergürtel entsteht aus den Gürteln und Bälgen der beiden vorigen Schritte.",en="The belt is made from the belts and hides of the two previous steps."},spell=3766,src="trainer",to=125},
    {crafts=7,from=125,mats={{2319,5}},note={de="Vorher den Experten-Rang lernen (ab Skill 125, Charakterstufe 20). Das Leder für die nächsten Schritte aufheben.",en="Learn Expert first (from skill 125, character level 20). Keep the leather for the next steps."},rank="expert",res={de="Umwandlung: aus mittlerem Leder wird schweres Leder, das ihr später braucht.",en="Conversion: medium leather becomes heavy leather, which you need later."},spell=20649,src="trainer",to=130},
    {crafts=21,from=130,mats={{2319,14},{2321,4}},note={de="Ab Skill 145 gelb: bei Pech ein paar Handschuhe und etwas Leder zusätzlich einplanen.",en="Yellow from 145: with bad luck, plan a few extra gloves and some spare leather."},rank="expert",res={de="Lederhandschuhe, für die ersten Schritte noch ohne teures schweres Leder.",en="Leather gloves that still avoid expensive heavy leather."},spell=3764,src="trainer",to=150},
    {bop=true,crafts=15,from=150,mats={{4234,10},{2321,2},{1206,1}},note={de="Das Muster ist beim Aufheben gebunden: Kauft es mit dem Lederer selbst, bevor ihr das Material besorgt. Das Angebot kann begrenzt sein. Alternative 130 bis 175 mit schweren Bälgen (ohne Moosachat und Händlermuster): Geschmeidiger schwerer Balg (ca. 20), Lederhandschuhe des Hügelwächters (ca. 16, bis 155), Barbarische Schultern (10, bis 165), Wächterhandschuhe (10, bis 175).",en="The pattern binds on pickup, so buy it with your own leatherworker before gathering materials. Stock may be limited. Alternative 130 to 175 with heavy hides (no Moss Agate or vendor pattern): Cured Heavy Hide (about 20), Hillman's Leather Gloves (about 16, to 155), Barbaric Shoulders (10, to 165), Guardian Gloves (10, to 175)."},npcs={{f="A",loc="Arathi Highlands, Refuge Pointe",locDe="Arathihochland, Zuflucht",n="Hammon Karwn",zone={de="Arathihochland",en="Arathi Highlands"}},{f="A",loc="Ashenvale, Astranaar",locDe="Eschental, Astranaar",n="Lardan",zone={de="Eschental",en="Ashenvale"}},{f="H",loc="Thousand Needles, Freewind Post",locDe="Tausend Nadeln, Freiwindposten",n="Jandia",zone={de="Tausend Nadeln",en="Thousand Needles"}},{f="H",loc="Arathi Highlands, Hammerfall",locDe="Arathihochland, Hammerfall",n="Keena",zone={de="Arathihochland",en="Arathi Highlands"}}},pat=5973,rank="expert",res={de="Lederhose mit Stärke, Beweglichkeit und Ausdauer; sie ist erst ab Charakterstufe 29 tragbar.",en="Leather leggings with strength, agility and stamina; wearable from character level 29."},spell=7149,src="item",to=165},
    {crafts=10,from=165,mats={{4234,16},{2325,1},{4291,2}},note={de="Bis Skill 180 orange. Nach den Gamaschen setzt ihr bei etwa 165 an.",en="Orange until 180. After the leggings you start at about 165."},rank="expert",res={de="Armschienen aus schwerem Leder.",en="Bracers made of heavy leather."},spell=9201,src="trainer",to=175},
    {crafts=5,from=175,mats={{4304,5},{4291,1}},note={de="Bis 195 orange. Prüft im Berufsfenster, ob das Rezept bei euch schon lernbar ist, bevor ihr teures dickes Leder kauft. Alternative 175 bis 200 mit schwerem statt dickem Leder: Barbarischer Harnisch (ca. 10, bis 185) und Schwärzlicher Gürtel (ca. 18, bis 200); die Eisernen Gürtelschnallen kommen vom Schmied oder aus dem Auktionshaus.",en="Orange until 195. Check your profession window that the recipe is learnable before buying expensive thick leather. Alternative 175 to 200 with heavy instead of thick leather: Barbaric Harness (about 10, to 185) and Dusky Belt (about 18, to 200); Iron Buckles come from a blacksmith or the auction house."},rank="expert",res={de="Rüstungsset aus dickem Leder; der Gegenstand nennt Rüstungswert und Stufenvoraussetzung.",en="Armor kit made of thick leather; the item lists its armor value and level requirement."},spell=10487,src="trainer",to=180},
    {crafts=20,from=180,mats={{4304,5},{4291,2}},note={de="Bis 200 orange, danach gelb. Auch hier vor dem Kauf prüfen, ob der Lehrer das Rezept schon anbietet.",en="Orange until 200, then yellow. Again, check whether your trainer already offers it before you buy."},rank="expert",res={de="Lederstirnband mit Beweglichkeit und Verstohlenheit.",en="Leather headband with agility and a stealth bonus."},spell=10507,src="trainer",to=200},
    {crafts=6,from=200,mats={{4304,5},{4291,2}},note={de="Ab 200 gelb, ein bis zwei Stücke Reserve einplanen.",en="Yellow from 200; plan one or two spare pieces."},rank="expert",res={de="Dieselbe Herstellung für die nächsten Punkte.",en="The same craft for the next few points."},spell=10507,src="trainer",to=205},
    {crafts=20,from=205,mats={{4304,14},{4291,4}},note={de="Bis 225 orange. Ob das Rezept ohne Fachmann-Ausbildung erreichbar ist, ist nicht gesichert: im Berufsfenster nachsehen, bevor ihr einkauft.",en="Orange until 225. It is not certain the recipe is reachable without the Artisan rank, so check your profession window before buying."},rank="expert",res={de="Lederhose mit Beweglichkeit und Ausdauer; tragbar ab Charakterstufe 41.",en="Leather pants with agility and stamina; wearable from character level 41."},spell=10548,src="trainer",to=225},
    {crafts=20,from=225,mats={{4304,6},{8154,8},{8343,2}},note={de="Das Muster fällt in Tanaris bei Wüstenläufern, vor allem bei Dieben; alternativ im Auktionshaus suchen. Bis 230 gelb, ab 240 grau: in kleinen Serien herstellen.",en="The pattern drops from desert runners in Tanaris, mostly the thieves; or look on the auction house. Yellow until 230, grey from 240: craft in small batches."},pat=8398,rank="artisan",res={de="Schwere Handschuhe mit Beweglichkeit und Intelligenz.",en="Heavy gloves with agility and intellect."},spell=10542,src="item",to=235},
    {crafts=35,from=235,mats={{4304,16},{8343,2}},note={de="Ab 240 grün; bei 250 zum nächsten Rezept wechseln.",en="Green from 240; switch to the next recipe at 250."},rank="artisan",res={de="Lederstiefel mit Beweglichkeit und einem Verstohlenheitsbonus.",en="Leather boots with agility and a stealth bonus."},spell=10558,src="trainer",to=250},
    {crafts=17,from=250,mats={{4304,10},{8154,20},{8343,2}},note={de="Das Muster fällt in Tanaris bei Wüstenläufern, besonders Assassinen; auch im Auktionshaus. Zunächst gelb, ab 255 grün.",en="The pattern drops from desert runners in Tanaris, mainly the assassins; also on the auction house. Yellow at first, green from 255."},pat=8402,rank="artisan",res={de="Schwerer Helm mit Beweglichkeit und Intelligenz.",en="Heavy helm with agility and intellect."},spell=10570,src="item",to=260},
    {bop=true,crafts=33,from=260,mats={{8170,8},{2325,1},{14341,1}},note={de="Das Muster ist begrenzt und beim Aufheben gebunden. Bis 265 gelb, danach grün: lieber in Portionen nachkaufen.",en="The pattern is limited and binds on pickup. Yellow until 265, then green: better to restock in portions."},npcs={{f="A",loc="Western Plaguelands",locDe="Westliche Pestländer",n="Leonard Porter",zone={de="Westliche Pestländer",en="Western Plaguelands"}},{f="H",loc="Tirisfal Glades",locDe="Tirisfal",n="Werg Thickblade",zone={de="Tirisfal",en="Tirisfal Glades"}}},pat=15725,rank="artisan",res={de="Lederhandschuhe mit Beweglichkeit und Ausdauer.",en="Leather gloves with agility and stamina."},spell=19049,src="item",to=275},
    {crafts=33,from=275,mats={{8170,6},{7971,1},{14047,6},{14341,1}},note={de="Das Muster fällt bei den Kultisten von Jaedenar im Teufelswald; alternativ im Auktionshaus. Ab 280 grün, ab 290 grau. Den Bedarf an Schwarzen Perlen vorab prüfen.",en="The pattern drops from the cultists of Jaedenar in Felwood; or buy it on the auction house. Green from 280, grey from 290. Check your Black Pearl supply in advance."},pat=15739,rank="artisan",res={de="Armschienen mit Intelligenz und Zauberschaden.",en="Bracers with intellect and spell damage."},spell=19065,src="item",to=290},
    {crafts=18,from=290,mats={{8170,14},{14047,10},{14341,1}},note={de="Das Angebot des Händlers ist begrenzt: besorgt das Muster mit dem Lederer selbst. Bis 295 gelb, danach grün; für den Endspurt Reserve einplanen.",en="The vendor stock is limited, so pick up the pattern with your own leatherworker. Yellow until 295, then green; plan spare materials for the final stretch."},npcs={{f="N",loc="Eastern Plaguelands",locDe="Östliche Pestländer",n="Jase Farlane",zone={de="Östliche Pestländer",en="Eastern Plaguelands"}}},pat=15756,rank="artisan",res={de="Lederhelm mit Intelligenz und Zaubermacht.",en="Leather helm with intellect and spell power."},spell=19082,src="item",to=300},
